bool isMember = true;
bool hasCoupon = false;
int age = 22;

// AND: both must be true
if (isMember && hasCoupon)
{
    Console.WriteLine("Both conditions met: 20% discount");
}
else
{
    Console.WriteLine("Discount not applied.");
}

// OR: at least one must be true
if (isMember || age >= 65)
{
    Console.WriteLine("Eligible for senior/member discount.");
}

// NOT: inverts the condition
bool isBanned = false;
if (!isBanned)
{
    Console.WriteLine("User can access the system.");
}

// Combining logical operators
if ((age >= 18 && age <= 65) && (isMember || hasCoupon))
{
    Console.WriteLine("Complex condition satisfied.");
}

// Avoid this: deeply nested
string ProcessUser(User user)
{
    if (user != null)
    {
        if (user.IsActive)
        {
            if (user.Age >= 18)
            {
                return "Access granted";
            }
            else
            {
                return "Too young";
            }
        }
        else
        {
            return "Account inactive";
        }
    }
    else
    {
        return "User is null";
    }
}

// Prefer this: guard clauses
string ProcessUser(User user)
{
    if (user == null) return "User is null";
    if (!user.IsActive) return "Account inactive";
    if (user.Age < 18) return "Too young";
    return "Access granted";
}

